// Cloudinary 数据层
// 方案C：signed 上传（api_secret 在前端），用于本地/私密使用

const CLOUD_NAME = process.env.VUE_APP_CLOUD_NAME
const API_KEY = process.env.VUE_APP_CLOUD_API_KEY+'8'
const API_SECRET = process.env.VUE_APP_CLOUD_API_SECRET+'ek'

const IMG_FOLDER = 'mhf'
const JSON_PUBLIC_ID = 'mhf/list.json'

// ---------- SHA1（纯 JS 实现，兼容非 HTTPS 环境） ----------
function utf8Encode(str) {
  const bytes = []
  for (let i = 0; i < str.length; i++) {
    let code = str.codePointAt(i)
    if (code > 0xffff) i++
    if (code < 0x80) {
      bytes.push(code)
    } else if (code < 0x800) {
      bytes.push(0xc0 | (code >> 6), 0x80 | (code & 0x3f))
    } else if (code < 0x10000) {
      bytes.push(0xe0 | (code >> 12), 0x80 | ((code >> 6) & 0x3f), 0x80 | (code & 0x3f))
    } else {
      bytes.push(
        0xf0 | (code >> 18),
        0x80 | ((code >> 12) & 0x3f),
        0x80 | ((code >> 6) & 0x3f),
        0x80 | (code & 0x3f)
      )
    }
  }
  return bytes
}

function rotl(n, b) {
  return ((n << b) | (n >>> (32 - b))) >>> 0
}

function sha1(str) {
  const msg = utf8Encode(str)
  const bitLen = msg.length * 8
  msg.push(0x80)
  while ((msg.length % 64) !== 56) msg.push(0)
  const hi = Math.floor(bitLen / 4294967296)
  const lo = bitLen >>> 0
  for (let i = 3; i >= 0; i--) msg.push((hi >>> (8 * i)) & 0xff)
  for (let i = 3; i >= 0; i--) msg.push((lo >>> (8 * i)) & 0xff)

  let h0 = 0x67452301
  let h1 = 0xefcdab89
  let h2 = 0x98badcfe
  let h3 = 0x10325476
  let h4 = 0xc3d2e1f0

  for (let block = 0; block < msg.length; block += 64) {
    const w = new Array(80)
    for (let i = 0; i < 16; i++) {
      const j = block + i * 4
      w[i] = (msg[j] << 24) | (msg[j + 1] << 16) | (msg[j + 2] << 8) | msg[j + 3]
    }
    for (let i = 16; i < 80; i++) {
      w[i] = rotl(w[i - 3] ^ w[i - 8] ^ w[i - 14] ^ w[i - 16], 1)
    }

    let a = h0
    let b = h1
    let c = h2
    let d = h3
    let e = h4

    for (let i = 0; i < 80; i++) {
      let f
      let k
      if (i < 20) {
        f = (b & c) | (~b & d)
        k = 0x5a827999
      } else if (i < 40) {
        f = b ^ c ^ d
        k = 0x6ed9eba1
      } else if (i < 60) {
        f = (b & c) | (b & d) | (c & d)
        k = 0x8f1bbcdc
      } else {
        f = b ^ c ^ d
        k = 0xca62c1d6
      }
      const temp = (rotl(a, 5) + f + e + k + w[i]) >>> 0
      e = d
      d = c
      c = rotl(b, 30)
      b = a
      a = temp
    }

    h0 = (h0 + a) >>> 0
    h1 = (h1 + b) >>> 0
    h2 = (h2 + c) >>> 0
    h3 = (h3 + d) >>> 0
    h4 = (h4 + e) >>> 0
  }

  return [h0, h1, h2, h3, h4]
    .map((x) => x.toString(16).padStart(8, '0'))
    .join('')
}

// ---------- 签名 ----------
function signParams(params) {
  const keys = Object.keys(params).sort()
  const base = keys.map((k) => `${k}=${params[k]}`).join('&')
  return sha1(base + API_SECRET)
}

function ensureConfig() {
  if (!CLOUD_NAME || !API_KEY || !API_SECRET) {
    throw new Error('缺少 Cloudinary 配置，请在 .env.local 中填写 API Key 与 API Secret')
  }
}

// ---------- 图片上传（本地 File 或 URL 字符串） ----------
export async function uploadImage(source) {
  ensureConfig()
  const timestamp = Math.floor(Date.now() / 1000).toString()
  const params = { folder: IMG_FOLDER, timestamp }
  const signature = signParams(params)

  const form = new FormData()
  form.append('file', source)
  form.append('api_key', API_KEY)
  form.append('timestamp', timestamp)
  form.append('signature', signature)
  form.append('folder', IMG_FOLDER)

  const res = await fetch(`https://api.cloudinary.com/v1_1/${CLOUD_NAME}/image/upload`, {
    method: 'POST',
    body: form
  })
  const data = await res.json()
  if (!res.ok || data.error) {
    throw new Error(data.error && data.error.message ? data.error.message : '图片上传失败')
  }
  return { url: data.secure_url, publicId: data.public_id }
}

// ---------- JSON 覆盖上传 ----------
export async function uploadJson(listData) {
  ensureConfig()
  const timestamp = Math.floor(Date.now() / 1000).toString()
  const params = {
    invalidate: 'true',
    overwrite: 'true',
    public_id: JSON_PUBLIC_ID,
    timestamp
  }
  const signature = signParams(params)

  const blob = new Blob([JSON.stringify(listData)], { type: 'application/json' })
  const form = new FormData()
  form.append('file', blob, 'list.json')
  form.append('api_key', API_KEY)
  form.append('timestamp', timestamp)
  form.append('signature', signature)
  form.append('public_id', JSON_PUBLIC_ID)
  form.append('overwrite', 'true')
  form.append('invalidate', 'true')

  const res = await fetch(`https://api.cloudinary.com/v1_1/${CLOUD_NAME}/raw/upload`, {
    method: 'POST',
    body: form
  })
  const data = await res.json()
  if (!res.ok || data.error) {
    throw new Error(data.error && data.error.message ? data.error.message : '数据保存失败')
  }
  return data
}

// ---------- 读取 JSON（首次使用返回 null） ----------
export async function fetchList() {
  if (!CLOUD_NAME) throw new Error('缺少 Cloudinary 配置')
  const url = `https://res.cloudinary.com/${CLOUD_NAME}/raw/upload/${JSON_PUBLIC_ID}`
  const res = await fetch(url, { cache: 'no-store' })
  if (!res.ok) {
    // 文件不存在（首次使用）
    if (res.status === 404 || res.status === 400) return null
    throw new Error('读取数据失败')
  }
  const text = await res.text()
  try {
    const data = JSON.parse(text)
    return data && Array.isArray(data.items) ? data : { items: [] }
  } catch (e) {
    return { items: [] }
  }
}

// ---------- 生成下载地址（fl_attachment 强制下载） ----------
export function getDownloadUrl(url) {
  return url.replace('/upload/', '/upload/fl_attachment/')
}
